package com.eia.contract.expert.bordereau;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * Create payload for a period bordereau.
 *
 * <p>The bordereau number is generated by the expert ({@code BRD-{YEAR}-{SEQ}})
 * and the status starts at {@code RECEIVED}, so neither is accepted from the
 * caller. Amounts are decimal JSON values (a number or a decimal string both
 * deserialize to {@link BigDecimal}) and must not be negative.</p>
 */
public record CreateBordereauRequest(
        LocalDate periodStart,
        LocalDate periodEnd,
        LocalDate receivedDate,
        String currency,
        BigDecimal premiumAmount,
        BigDecimal lossAmount,
        BigDecimal commissionAmount,
        BigDecimal otherChargesAmount,
        Integer lineCount,
        String notes
) {}
